def alg(inp):
    out=[row.copy() for row in inp]
    # clear left part
    for r in range(8):
        for c in range(9): out[r][c]=0
    # shift interior upward, copy r+1, for r1-5 ; r6 blank. cols10-18
    for r in range(1,7):
        for c in range(10,19):
            out[r][c] = inp[r+1][c] if r+1 <= 6 else 0
    # overlay left pattern as 5s onto right at +10 same row
    for r in range(8):
        for c in range(9):
            if inp[r][c]==5: out[r][c+10]=5
    return out
